"""The schema of the MPVI planner call (design plan 8, D4 addendum), as a Pydantic model.

The planner call uses enforced structured output: the provider is given the JSON schema of the model (`Plan.model_json_schema()`) through its native structured-output support, and the reply
is validated again here with `model_validate`, so a reply that does not fit stops the plan before it starts.

    Plan      the planning call's reply: the paper's segment fields (Appendices C.1 and D): {"task_name", "segments": [{"type", "description", "completion_criteria", "target"}]} PLUS two
              fields on every manipulation segment, `primitive` (pick, place or other) and `objects` (the object phrases the description refers to, each with a role). Both are null for
              navigation segments. (David, 2026-10-23: one planner call replaces the planner plus the separate labeling call; the paper does not say how its labeling works, E3. The fields are
              explained in the schema's field descriptions, which the provider sees, not in the prompt, which stays word for word.)

Contents:
    Primitive, Role, ObjectPhrase: the labeling vocabulary.
    Segment, Plan: the planning schema.
"""

from enum import Enum
from typing import Literal, Optional

from pydantic import BaseModel, ConfigDict, Field, model_validator


class Primitive(str, Enum):
    """What a manipulation segment maps to: the scripted skills pick and place, or "other" (no skill: the step stops when it starts)."""

    pick = "pick"
    place = "place"
    other = "other"


class Role(str, Enum):
    """What an object phrase is in its step: the object acted on, or where it goes (the place's surface)."""

    manipulated = "manipulated"
    destination = "destination"


class ObjectPhrase(BaseModel):
    """An object phrase as written in the step's description, with its role."""

    model_config = ConfigDict(extra="forbid")

    phrase: str = Field(min_length=1)
    role: Role


class Segment(BaseModel):
    """One segment of the plan: the paper's fields, and for manipulation segments the primitive and the object phrases."""

    model_config = ConfigDict(extra="forbid")

    type: Literal["navigation", "manipulation"]
    description: str = Field(min_length=1)
    completion_criteria: str = Field(min_length=1)
    target: Optional[str] = None
    primitive: Optional[Primitive] = Field(default=None, description=(
        "Manipulation segments only (null for navigation segments): which primitive the step maps to. pick: the gripper takes an object. place: the gripper puts the held object down. "
        "other: neither of the two."))
    objects: Optional[list[ObjectPhrase]] = Field(default=None, description=(
        "Manipulation segments only (null for navigation segments): the object phrases the step's description refers to, each copied as written in the description, with its role. "
        "manipulated: the object acted on. destination: the surface or place the object goes to. An empty list if the description names no object."))

    @model_validator(mode="after")
    def _fields_by_type(self):
        if (self.type == "navigation") != (self.target is not None):
            raise ValueError("the target is given for navigation segments only")
        if self.type == "navigation" and (self.primitive is not None or self.objects is not None):
            raise ValueError("a navigation segment has no primitive and no objects (they are for manipulation segments only)")
        if self.type == "manipulation" and (self.primitive is None or self.objects is None):
            raise ValueError("a manipulation segment needs its primitive and its objects")
        return self


class Plan(BaseModel):
    """The planner's reply: the task name and at least one segment."""

    model_config = ConfigDict(extra="forbid")

    task_name: str = Field(min_length=1)
    segments: list[Segment] = Field(min_length=1)
